import numpy as np
import math

def generate(params, n, chip):
    h = int(round(params['hub_size']))
    s = int(round(params['n_spokes']))
    L = int(round(params['spoke_len']))
    w = int(round(params['spoke_w']))

    # Ensure even width for symmetric placement
    if w % 2 != 0:
        w += 1
    half_w = w // 2

    grid = np.zeros((n, n), dtype=bool)
    i0, i1, j0, j1 = chip
    ci = (i0 + i1) // 2
    cj = (j0 + j1) // 2

    # Clamp hub size to stay within bounds and not exceed chip area significantly
    max_hub = min(ci, cj, n - 1 - ci, n - 1 - cj)
    h = min(h, max_hub * 2 + 1)  # ensure hub fits
    if h < 1:
        h = 1
    if h % 2 == 0:
        h += 1  # keep odd for center symmetry
    half_h = h // 2

    # Fill hub
    i_start = ci - half_h
    i_end = ci + half_h + 1
    j_start = cj - half_h
    j_end = cj + half_h + 1
    i_start = max(0, i_start)
    i_end = min(n, i_end)
    j_start = max(0, j_start)
    j_end = min(n, j_end)
    grid[i_start:i_end, j_start:j_end] = True

    # Directions for spokes: up, down, left, right, and diagonals if needed
    angles = [2 * math.pi * k / s for k in range(s)]
    dirs = [(int(round(math.cos(a))), int(round(math.sin(a)))) for a in angles]
    # Remove zero vector
    dirs = [d for d in dirs if d != (0, 0)]
    # Normalize to avoid duplicate directions due to rounding
    unique_dirs = []
    seen = set()
    for d in dirs:
        # Reduce to simplest integer form for consistency
        g = math.gcd(abs(d[0]), abs(d[1])) if d != (0, 0) else 1
        nd = (d[0] // g, d[1] // g) if g != 0 else (0, 0)
        if nd not in seen:
            seen.add(nd)
            unique_dirs.append(nd)
    dirs = unique_dirs
    if not dirs:
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]  # fallback

    # Grow spokes from hub edge
    spoke_cells = set()
    for dx, dy in dirs:
        # Start from hub edge in direction (dx, dy)
        if dx > 0:
            si = ci + half_h
        elif dx < 0:
            si = ci - half_h
        else:
            si = ci
        if dy > 0:
            sj = cj + half_h
        elif dy < 0:
            sj = cj - half_h
        else:
            sj = cj

        for step in range(L):
            ni = si + dx * step
            nj = sj + dy * step
            if 0 <= ni < n and 0 <= nj < n:
                # Expand spoke to width w perpendicular to (dx, dy)
                if dx == 0 and dy == 0:
                    continue
                elif dx == 0:  # vertical spoke
                    for offset in range(-half_w, half_w + 1):
                        njj = nj + offset
                        if 0 <= njj < n:
