                        nii = ni + offset
                        if 0 <= nii < n:
                            spoke_cells.add((nii, nj))
                else:  # diagonal spoke: approximate width via orthogonal offset
                    # Perpendicular direction: (-dy, dx)
                    px, py = -dy, dx
