    # Add spoke cells to grid
    for (i, j) in spoke_cells:
        if 0 <= i < n and 0 <= j < n:
            grid[i, j] = True

    # Ensure chip is covered (should be by hub, but double-check)
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                grid[i, j] = True

    # Enforce connectivity: flood fill from chip
    visited = np.zeros_like(grid, dtype=bool)
    stack = []
    # Start from chip center or any chip cell
    start_i, start_j = ci, cj
    if not (0 <= start_i < n and 0 <= start_j < n):
        start_i, start_j = i0, j0
    if grid[start_i, start_j]:
        stack.append((start_i, start_j))
        visited[start_i, start_j] = True

    while stack:
