    if not np.array_equal(grid, visited):
        grid = visited  # Keep only the connected component containing the chip

    # Enforce minimum feature size: remove isolated pixels or thin connections <2 cells
    # We do this by ensuring that any material cell has at least one neighbor in each direction? 
