    # But to be safe, we can do a simple erosion/dilation to enforce min width 2.
    # However, to avoid complexity and since we construct with width, we skip aggressive cleaning.
    # Instead, we ensure that during spoke generation, width >=2 is maintained.

    # Final check: enforce cell count <= 1440 by trimming excess spokes if needed
    material_count = np.sum(grid)
    if material_count > 1440:
        # Truncate spokes from the end
        excess = material_count - 1440
        # Flatten spoke cells and sort by distance from chip center (farthest first)
        spoke_list = []
        for dx, dy in dirs:
            if dx > 0:
                si = ci + half_h
            elif dx < 0:
                si = ci - half_h
            else:
                si = ci
            if dy > 0:
                sj = cj + half_h
            elif dy < 0:
                sj = cj - half_h
            else:
                sj = cj
            for step in range(L):
                ni = si + dx * step
                nj = sj + dy * step
                if 0 <= ni < n and 0 <= nj < n:
