                        for offset in range(-half_w, half_w + 1):
                            njj = nj + offset
                            if 0 <= njj < n:
                                spoke_list.append((ni, njj, step))
                    elif dy == 0:
                        for offset in range(-half_w, half_w + 1):
                            nii = ni + offset
                            if 0 <= nii < n:
                                spoke_list.append((nii, nj, step))
                    else:
                        px, py = -dy, dx
                        g = math.gcd(abs(px), abs(py))
                        if g != 0:
                            px //= g
                            py //= g
                        for offset in range(-half_w, half_w + 1):
                            nii = ni + px * offset
                            njj = nj + py * offset
                            if 0 <= nii < n and 0 <= njj < n:
                                spoke_list.append((nii, njj, step))
        # Sort by step descending (farthest first)
        spoke_list.sort(key=lambda x: x[2], reverse=True)
        removed = 0
        for (i, j, _) in spoke_list:
            if removed >= excess:
                break
            if grid[i, j]:
                # Check if removing this cell breaks connectivity or chip connection
                # Temporarily remove
                grid[i, j] = False
                # Re-check connectivity from chip
                visited = np.zeros_like(grid, dtype=bool)
                stack = []
                if grid[ci, cj]:
