import numpy as np
from collections import deque

def generate(params, n, chip):
    levels = int(params['levels'])
    base_spine_w = int(params['base_spine_w'])
    fin_w = int(params['fin_w'])
    max_fin_len = int(params['max_fin_len'])

    def clamp(x, lo, hi):
        return max(lo, min(hi, x))

    grid = np.zeros((n, n), dtype=bool)
    i0, i1, j0, j1 = chip

    # Chip region as material
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n:
                grid[i, j] = True

    cx = (i0 + i1) // 2
    cy = (j0 + j1) // 2

    def add_cross(xc, yc, spine_h, spine_v, fw, fl):
        half_h = spine_h // 2
        half_v = spine_v // 2
        half_fw = fw // 2

        # Horizontal spine
        y_start = yc - half_h
        y_end = yc + half_h
        for y in range(y_start, y_end + 1):
            if 0 <= y < n:
                for x in range(max(0, xc - fl), min(n, xc + fl + 1)):
                    grid[x, y] = True

        # Vertical spine
        x_start = xc - half_v
        x_end = xc + half_v
        for x in range(x_start, x_end + 1):
            if 0 <= x < n:
                for y in range(max(0, yc - fl), min(n, yc + fl + 1)):
                    grid[x, y] = True

    def subdivide(xc, yc, size, level):
        if level >= levels:
            return
        spine_h = max(base_spine_w // (2 ** level), 2)
        spine_v = max(base_spine_w // (2 ** level), 2)
        fl = max_fin_len // (2 ** level)
        if fl < 2:
            fl = 2
        add_cross(xc, yc, spine_h, spine_v, fin_w, fl)
        half = size // 2
        if half < 1:
            return
        subdivide(xc - half, yc - half, half, level + 1)
        subdivide(xc + half, yc - half, half, level + 1)
        subdivide(xc - half, yc + half, half, level + 1)
        subdivide(xc + half, yc + half, half, level + 1)

    subdivide(cx, cy, n // 2, 0)

    # Flood fill from chip to enforce connectivity
    visited = np.zeros_like(grid, dtype=bool)
    dq = deque()
    for i in range(i0, i1 + 1):
        for j in range(j0, j1 + 1):
            if 0 <= i < n and 0 <= j < n and grid[i, j]:
                visited[i, j] = True
                dq.append((i, j))
    while dq:
        x, y = dq.popleft()
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx, ny] and not visited[nx, ny]:
                visited[nx, ny] = True
                dq.append((nx, ny))
    grid &= visited

    # Enforce cell budget by trimming farthest from chip
    if np.sum(grid) > 1440:
        material_coords = np.argwhere(grid)
        if len(material_coords) > 0:
            dists = np.maximum(
                np.maximum(i0 - material_coords[:, 0], material_coords[:, 0] - i1),
                np.maximum(j0 - material_coords[:, 1], material_coords[:, 1] - j1)
            )
            dists = np.maximum(dists, 0)
            idx_sorted = np.argsort(dists)
            keep = np.zeros_like(grid, dtype=bool)
            keep[tuple(material_coords[idx_sorted[:1440]].T)] = True
            grid = keep

    return grid
